'use client';

import { useId, useState } from 'react';
import type { MouseEvent } from 'react';
import './pricing-plans.css';

export type BillingPeriod = 'monthly' | 'yearly';

export interface PricingPlan {
  id: string;
  name: string;
  description: string;
  monthly: number;
  yearly: number;
  features: string[];
  href: string;
  ctaLabel?: string;
  featured?: boolean;
}

export interface PricingPlansProps {
  plans: PricingPlan[];
  title?: string;
  currency?: string;
  locale?: string;
  defaultBilling?: BillingPeriod;
  onBillingChange?: (period: BillingPeriod) => void;
  onSelect?: (plan: PricingPlan, period: BillingPeriod, event: MouseEvent<HTMLAnchorElement>) => void;
  className?: string;
}

/** Clear, annual-total pricing with ordinary links for the next step. */
export function PricingPlans({
  plans,
  title = 'A plan for your next chapter',
  currency = 'USD',
  locale = 'en-US',
  defaultBilling = 'monthly',
  onBillingChange,
  onSelect,
  className = '',
}: PricingPlansProps) {
  const headingId = useId();
  const [billing, setBilling] = useState<BillingPeriod>(defaultBilling);
  const format = new Intl.NumberFormat(locale, {
    style: 'currency', currency, minimumFractionDigits: 0,
  });
  const precision = 10 ** (format.resolvedOptions().maximumFractionDigits ?? 2);

  function changeBilling(next: BillingPeriod) {
    if (next === billing) return;
    setBilling(next);
    onBillingChange?.(next);
  }

  if (!plans.length) return null;

  return (
    <section className={`ac-pricing-plans ${className}`.trim()} aria-labelledby={headingId}>
      <header className="ac-pricing-header">
        <div>
          <span className="ac-pricing-eyebrow">ROOM TO GROW</span>
          <h2 id={headingId}>{title}</h2>
        </div>
        <div className="ac-pricing-billing" role="group" aria-label="Billing period">
          <button type="button" aria-pressed={billing === 'monthly'} onClick={() => changeBilling('monthly')}>Monthly</button>
          <button type="button" aria-pressed={billing === 'yearly'} onClick={() => changeBilling('yearly')}>Yearly</button>
        </div>
      </header>

      <div className="ac-pricing-grid">
        {plans.map(plan => {
          const amount = billing === 'yearly' ? plan.yearly : plan.monthly;
          const saving = Math.round((plan.monthly * 12 - plan.yearly) * precision) / precision;
          return (
            <article className={`ac-pricing-card${plan.featured ? ' ac-pricing-featured' : ''}`} key={plan.id}>
              <div className="ac-pricing-card-heading">
                <h3>{plan.name}</h3>
                {plan.featured && <span className="ac-pricing-badge">A little more room</span>}
              </div>
              <p className="ac-pricing-description">{plan.description}</p>
              <div className="ac-pricing-price" aria-live="polite" aria-atomic="true">
                <p><strong>{format.format(amount)}</strong><span> / {billing === 'yearly' ? 'year' : 'month'}</span></p>
                <span className="ac-pricing-billing-note">{billing === 'yearly' ? 'Billed annually' : 'Billed monthly'}</span>
                {billing === 'yearly' && saving > 0 && <span className="ac-pricing-saving">Save {format.format(saving)} per year</span>}
              </div>
              <ul className="ac-pricing-features" aria-label={`${plan.name} includes`}>
                {plan.features.map((feature, index) => <li key={`${feature}-${index}`}><span aria-hidden="true">✓</span>{feature}</li>)}
              </ul>
              <a className="ac-pricing-cta" href={plan.href} onClick={event => onSelect?.(plan, billing, event)}>
                {plan.ctaLabel ?? `Choose ${plan.name}`}<span aria-hidden="true">↗</span>
              </a>
            </article>
          );
        })}
      </div>
    </section>
  );
}

.ac-pricing-plans {
  --ac-pricing-surface: var(--ac-pricing-theme-surface, #eeeede);
  --ac-pricing-card: var(--ac-pricing-theme-card, #f8f8ee);
  --ac-pricing-ink: var(--ac-pricing-theme-ink, #283226);
  --ac-pricing-muted: var(--ac-pricing-theme-muted, #606b5c);
  --ac-pricing-accent: #334b35;
  --ac-pricing-featured: #d8e4b3;
  --ac-pricing-line: var(--ac-pricing-theme-line, #28322625);
  --ac-pricing-font: inherit;
  box-sizing: border-box;
  container-type: inline-size;
  width: 100%;
  padding: clamp(20px, 4cqw, 48px);
  background: var(--ac-pricing-surface);
  color: var(--ac-pricing-ink);
  font-family: var(--ac-pricing-font);
}

.ac-pricing-plans * { box-sizing: border-box; }
.ac-pricing-header {
  display: flex;
  flex-wrap: wrap;
  align-items: end;
  justify-content: space-between;
  gap: 24px;
  margin-bottom: 30px;
}
.ac-pricing-eyebrow { font-size: 10px; font-weight: 600; letter-spacing: .12em; }
.ac-pricing-header h2 {
  max-width: 20ch;
  margin: 12px 0 0;
  font-size: clamp(28px, 4cqw, 43px);
  line-height: 1.08;
  font-weight: 500;
  letter-spacing: -.05em;
}
.ac-pricing-billing {
  display: inline-flex;
  gap: 3px;
  padding: 4px;
  border: 1px solid var(--ac-pricing-line);
  border-radius: 99px;
  background: var(--ac-pricing-card);
}
.ac-pricing-billing button {
  appearance: none;
  min-height: 38px;
  padding: 9px 18px;
  border: 0;
  border-radius: 99px;
  background: transparent;
  color: var(--ac-pricing-muted);
  font: inherit;
  font-size: 12px;
  line-height: 1.3;
  cursor: pointer;
  transition: background .2s, color .2s;
}
.ac-pricing-billing button[aria-pressed="true"] { background: var(--ac-pricing-ink); color: var(--ac-pricing-card); }
.ac-pricing-plans :is(button, a):focus-visible { outline: 2px solid var(--ac-pricing-accent); outline-offset: 4px; }
.ac-pricing-grid { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 14px; }
.ac-pricing-card {
  display: flex;
  flex-direction: column;
  min-width: 0;
  padding: clamp(20px, 2.7cqw, 30px);
  border: 1px solid var(--ac-pricing-line);
  border-radius: 12px;
  background: var(--ac-pricing-card);
}
.ac-pricing-featured { background: var(--ac-pricing-featured); }
.ac-pricing-card-heading { display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between; gap: 9px; }
.ac-pricing-card h3 { margin: 0; font-size: 19px; font-weight: 500; letter-spacing: -.04em; }
.ac-pricing-badge { padding: 5px 8px; border: 1px solid var(--ac-pricing-line); border-radius: 99px; font-size: 9px; line-height: 1.2; }
.ac-pricing-description { margin: 12px 0 0; color: var(--ac-pricing-muted); font-size: 12px; line-height: 1.6; }
.ac-pricing-price { display: flex; flex-wrap: wrap; align-items: center; gap: 7px 10px; min-height: 95px; padding: 21px 0 18px; }
.ac-pricing-price p { flex-basis: 100%; margin: 0; line-height: 1; }
.ac-pricing-price strong { font-size: clamp(34px, 4cqw, 46px); font-weight: 500; letter-spacing: -.06em; }
.ac-pricing-price p > span, .ac-pricing-billing-note { font-size: 11px; color: var(--ac-pricing-muted); }
.ac-pricing-saving { font-size: 10px; color: var(--ac-pricing-accent); }
.ac-pricing-features { display: grid; gap: 12px; margin: 0 0 26px; padding: 21px 0 0; border-top: 1px solid var(--ac-pricing-line); list-style: none; }
.ac-pricing-features li { display: flex; align-items: baseline; gap: 10px; font-size: 12px; line-height: 1.45; }
.ac-pricing-features li > span { color: var(--ac-pricing-accent); }
.ac-pricing-cta { display: flex; align-items: center; justify-content: space-between; gap: 14px; min-height: 44px; margin-top: auto; padding: 11px 14px; border: 1px solid var(--ac-pricing-line); border-radius: 6px; color: var(--ac-pricing-ink); font-size: 12px; line-height: 1.5; text-decoration: none; transition: background .2s, color .2s; }
.ac-pricing-featured .ac-pricing-cta, .ac-pricing-cta:hover { background: var(--ac-pricing-ink); color: var(--ac-pricing-card); }
.ac-pricing-cta > span { font-size: 18px; line-height: 1; }

@container (max-width: 760px) {
  .ac-pricing-header { align-items: start; gap: 19px; }
  .ac-pricing-grid { display: flex; gap: 12px; overflow-x: auto; padding: 4px 4px 15px; margin: -4px; scroll-snap-type: x mandatory; scroll-padding: 4px; overscroll-behavior-x: contain; }
  .ac-pricing-card { flex: 0 0 min(280px, 100%); scroll-snap-align: start; padding: 23px; }
  .ac-pricing-price strong { font-size: 39px; }
}
@media (prefers-reduced-motion: reduce) {
  .ac-pricing-billing button, .ac-pricing-cta { transition: none; }
}

/* Neutral surfaces follow an explicit page theme; artwork and accents keep their palette. */
:where([data-theme="light"]) .ac-pricing-plans {
  --ac-pricing-theme-card: #ffffff;
  --ac-pricing-theme-ink: #202722;
  --ac-pricing-theme-line: #d7ded4;
  --ac-pricing-theme-muted: #687269;
  --ac-pricing-theme-surface: #fafbf8;
  color-scheme: light;
}
:where([data-theme="dark"], .dark) .ac-pricing-plans {
  --ac-pricing-theme-card: #242c26;
  --ac-pricing-theme-ink: #edf2eb;
  --ac-pricing-theme-line: #3d483e;
  --ac-pricing-theme-muted: #a7b3a3;
  --ac-pricing-theme-surface: #191e1b;
  color-scheme: dark;
}


/* The featured plan is a colored design element in both themes. */
.ac-pricing-featured { --ac-pricing-ink: #283226; --ac-pricing-muted: #606b5c; --ac-pricing-line: #28322625; --ac-pricing-card: #f8f8ee; }
:where([data-theme="dark"], .dark) .ac-pricing-card:not(.ac-pricing-featured) .ac-pricing-saving,
:where([data-theme="dark"], .dark) .ac-pricing-card:not(.ac-pricing-featured) .ac-pricing-features li > span { color: #b2ce9d; }
:where([data-theme="dark"], .dark) .ac-pricing-plans :is(button, a):focus-visible { outline-color: var(--ac-pricing-ink); }
